9	/// The serialisation format for `AgentResponse::render`.
10	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
11	#[non_exhaustive]
12	pub enum OutputFormat {
13	    /// Plain-text TOON / kv format. Default.
14	    #[default]
15	    Text,
16	    /// Compact JSON object.
17	    Json,
18	}
19	
20	/// Default per-cell truncation limit used by [`AgentResponse::new`].
21	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
22	
23	/// Builder for an agent-facing response: an ordered list of [`Section`]s, an optional budget report and provenance
24	/// block, hints and recovery hints.
25	#[derive(Debug, Clone)]
26	#[non_exhaustive]
27	pub struct AgentResponse {
28	    /// The type name given to [`new`](Self::new): it names the sections that [`items`](Self::items) and
29	    /// [`kv_items`](Self::kv_items) append, and the empty list an untouched response renders.
30	    name: String,
31	    /// Per-cell cap for every `Toon` section, set with [`truncate_cells_at`](Self::truncate_cells_at).
32	    max_cell_len: usize,
33	    /// The caller's instruction for getting a cut cell in full, set with [`truncation_hint`](Self::truncation_hint).
34	    truncation_hint: Option<String>,
35	    /// Every block, in call order. The one place a response keeps its body.
36	    sections: Vec<Section>,
37	    /// Response-level budget report, set with `budget()`.
38	    budget: Option<BudgetSummary>,
39	    /// Response-level provenance block, set with `provenance()`.
40	    provenance: Option<ProvenanceBlock>,
41	    hints: Vec<Hint>,
42	    recovery: Vec<RecoveryHint>,
43	    is_error: bool,
44	    human_content: Option<String>,
45	}
46	
47	impl AgentResponse {
48	    /// Create a new, empty response for the given type name. The name labels the sections that
49	    /// [`items`](Self::items) and [`kv_items`](Self::kv_items) add. A response that never gets a section, budget or
50	    /// provenance renders `name: []`, the definitive empty list.
51	    pub fn new(type_name: impl Into<String>) -> Self {
52	        Self {
53	            name: type_name.into(),
54	            max_cell_len: DEFAULT_TRUNCATE_CELLS,
55	            truncation_hint: None,
56	            sections: Vec::new(),
57	            budget: None,
58	            provenance: None,
59	            hints: Vec::new(),
60	            recovery: Vec::new(),
61	            is_error: false,
62	            human_content: None,
63	        }
64	    }
65	
66	    /// Append a TOON list section named for the response's type: shorthand for
67	    /// `section(Section::toon(name, fields, rows))`. Every call adds a section, so calling it twice, or mixing it with
68	    /// [`kv_items`](Self::kv_items), renders every body in call order. To report a total, build the section yourself
69	    /// and set [`Section::total_count`].
70	    #[must_use]
71	    pub fn items(self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
72	        let name = self.name.clone();
73	        self.section(Section::toon(name, fields.iter().map(|s| (*s).to_string()).collect(), rows))
74	    }
75	
76	    /// Append a section for a cut list, in one call: `section` gets `totalCount` (`outcome.total_before`) and its
77	    /// `truncated` flag from `outcome`, and, only when something was cut, [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint) is appended to
78	    /// the hints. The count and the `help[]` line therefore always describe the same cut.
79	    ///
80	    /// The response holds TOON [`Value`] rows, not the caller's `T`, so build `section` from `outcome.kept`
81	    /// (converted to rows). `totalCount` renders only when `total_before` exceeds the section's rows.
82	    ///
83	    /// ```
84	    /// use michi_core::toon::Value;
85	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat, Section};
86	    ///
87	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
88	    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
89	    /// let r = AgentResponse::new("issues").truncated_section(
90	    ///     Section::toon("issues", vec!["n".into()], rows),
91	    ///     &outcome,
92	    ///     "pass --limit 4",
93	    /// );
94	    /// assert_eq!(
95	    ///     r.render(OutputFormat::Text),
96	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
97	    /// );
98	    /// ```
99	    #[must_use]
100	    pub fn truncated_section<T>(
101	        mut self,
102	        section: Section,
103	        outcome: &crate::truncation::TruncationOutcome<T>,
104	        guidance: impl Into<String>,
105	    ) -> Self {
106	        if let Some(hint) = outcome.hint(guidance) {
107	            self.hints.push(hint);
108	        }
109	        self.section(section.total_count(Some(outcome.total_before)).truncated(outcome.truncated()))
110	    }
111	
112	    /// Append a KV section named for the response's type: shorthand for `section(Section::kv(name, items))`. The name
113	    /// is not printed for a KV body. Every call adds a section; see [`items`](Self::items).
114	    #[must_use]
115	    pub fn kv_items(self, items: Vec<KvItem>) -> Self {
116	        let name = self.name.clone();
117	        self.section(Section::kv(name, items))
118	    }
119	
120	    /// Append a section. Sections render in call order, the one place a response keeps its body: the caller owns
121	    /// ordering.
122	    ///
123	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
124	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`].
125	    #[must_use]
126	    pub fn section(mut self, section: Section) -> Self {
127	        self.sections.push(section);
128	        self
129	    }
130	
131	    /// Attach the response-level budget report; one per response, a second call replaces the first. It renders as a
132	    /// `budget:` block after the last section (see [`BudgetSummary`] for what it carries), and the per-section
133	    /// roll-up appears only when the response has two or more sections. michi renders the report; it never computes
134	    /// it.
135	    ///
136	    /// A response with a budget or provenance but no section has no body of its own: the empty `type: []` line that
137	    /// an untouched response renders is left out.
138	    #[must_use]
139	    pub fn budget(mut self, budget: BudgetSummary) -> Self {
140	        self.budget = Some(budget);
141	        self
142	    }
143	
144	    /// Attach the response-level provenance block; one per response, a second call replaces the first. It renders as
145	    /// a `provenance:` block after `budget:` (see [`ProvenanceBlock`]).
146	    #[must_use]
147	    pub fn provenance(mut self, provenance: ProvenanceBlock) -> Self {
148	        self.provenance = Some(provenance);
149	        self
150	    }
151	
152	    /// Append a contextual hint.
153	    #[must_use]
154	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
155	        self.hints.push(Hint::new(hint));
156	        self
157	    }
158	
159	    /// Replace all contextual hints.
160	    #[must_use]
161	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
162	        self.hints = hints;
163	        self
164	    }
165	
166	    /// Append a recovery hint.
167	    #[must_use]
168	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
169	        self.recovery.push(r);
170	        self
171	    }
172	
173	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
174	    /// [`DEFAULT_TRUNCATE_CELLS`].
175	    ///
176	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
177	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
178	    #[must_use]
179	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
180	        self.max_cell_len = limit;
181	        self
182	    }
183	
184	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
185	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction (see
186	    /// [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: michi never invents a parameter the tool
187	    /// may not have, and the `truncated` block still reports each cut. Pass tool-author text, never data.
188	    #[must_use]
189	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
190	        self.truncation_hint = Some(hint.into());
191	        self
192	    }
193	
194	    /// Mark this response as an error state.
195	    #[must_use]
196	    pub fn as_error(mut self) -> Self {
197	        self.is_error = true;
198	        self
199	    }
200	
201	    /// Attach a human-facing companion block (`audience: user`).
202	    #[must_use]
203	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
204	        self.human_content = Some(text.into());
205	        self
206	    }
207	
208	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
209	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
210	        if extra.is_empty() {
211	            std::borrow::Cow::Borrowed(&self.hints)
212	        } else {
213	            let mut all = Vec::with_capacity(self.hints.len() + extra.len());
214	            all.extend(self.hints.iter().cloned());
215	            all.extend(extra.iter().cloned());
216	            std::borrow::Cow::Owned(all)
217	        }
218	    }
219	
220	    /// The options a `Toon` section renders by: the response's cell cap and truncation hint, the section's own
221	    /// `totalCount` rule. Copies the rows: `ToonOptions` owns them.
222	    fn section_options(
223	        &self,
224	        name: &str,
225	        fields: &[String],
226	        rows: &[Vec<Value>],
227	        shown_total: Option<usize>,
228	    ) -> crate::toon::ToonOptions {
229	        let mut opts = crate::toon::ToonOptions::new(name, fields.to_vec(), rows.to_vec());
230	        opts.total_count = shown_total;
231	        opts.max_cell_len = self.max_cell_len;
232	        opts.truncation_hint.clone_from(&self.truncation_hint);
233	        opts
234	    }
235	
236	    /// The blocks to render: the sections, or, for a response with nothing at all, the one empty list that names
237	    /// its type. A budget or provenance block stands alone, with no empty list before it.
238	    fn blocks(&self) -> std::borrow::Cow<'_, [Section]> {
239	        if self.sections.is_empty() && self.budget.is_none() && self.provenance.is_none() {
240	            std::borrow::Cow::Owned(vec![Section::toon(self.name.as_str(), Vec::new(), Vec::new())])
241	        } else {
242	            std::borrow::Cow::Borrowed(&self.sections)
243	        }
244	    }
245	
246	    /// One section as an envelope part.
247	    fn section_part<'a>(&self, s: &'a Section) -> (Part<'a>, bool, Option<Hint>) {
248	        let total = s.shown_total();
249	        match &s.body {
250	            SectionBody::Toon { fields, rows } => match self.section_options(&s.name, fields, rows, total).validate() {
251	                Ok(doc) => {
252	                    let (text, cuts, extra) = doc.render_parts(false);
253	                    (Part { name: &s.name, text, cuts, total }, false, extra.map(Hint::new))
254	                }
255	                Err(e) => (Part::failed(&s.name, "toon_validation_failed", &e.to_string()), true, None),
256	            },
257	            SectionBody::Kv(items) => kv_part(&s.name, items, total),
258	            SectionBody::Text(text) => {
259	                (Part { name: &s.name, text: text.clone(), cuts: Vec::new(), total: None }, false, None)
260	            }
261	        }
262	    }
263	
264	    /// The body: sections, `budget:`, `provenance:`.
265	    ///
266	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
267	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
268	    /// one table with a leading `section` column, after the last block.
269	    ///
270	    /// The flag is whether this response is an error: set by `as_error()` or by a block that failed validation.
271	    /// Every output surface reads its error flag from here so text, JSON and MCP never disagree.
272	    fn body(&self) -> (String, bool, Vec<Hint>) {
273	        let blocks = self.blocks();
274	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
275	        let mut failed = false;
276	        let mut extras: Vec<Hint> = Vec::new();
277	        for s in blocks.iter() {
278	            let (part, part_failed, extra) = self.section_part(s);
279	            failed |= part_failed;
280	            // One line per cut response is enough: every section's line says the same thing.
281	            if let Some(h) = extra {
282	                if !extras.contains(&h) {
283	                    extras.push(h);
284	                }
285	            }
286	            parts.push(part);
287	        }
288	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
289	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
290	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
291	        for p in &parts {
292	            join_block(&mut out, &p.text);
293	            if cutters == 1 && !p.cuts.is_empty() {
294	                join_block(&mut out, &truncated_table(std::slice::from_ref(p)));
295	            }
296	            if let (1, Some(n)) = (totals, p.total) {
297	                join_block(&mut out, &format!("totalCount: {n}"));
298	            }
299	        }
300	        if cutters >= 2 {
301	            join_block(&mut out, &truncated_table(&parts));
302	        }
303	        if totals >= 2 {
304	            join_block(&mut out, &total_table(&parts));
305	        }
306	        if let Some(b) = &self.budget {
307	            join_block(&mut out, &crate::budget::render_budget_block(b, self.sections.len() >= 2));
308	        }
309	        if let Some(p) = &self.provenance {
310	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
311	        }
312	        (out, failed || self.is_error, extras)
313	    }
314	
315	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
316	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
317	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
318	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
319	        let hints = self.hints_with(extra);
320	        if !hints.is_empty() || !self.recovery.is_empty() {
321	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
322	        }
323	        crate::hints::append_hints(&mut body, &hints);
324	        crate::recovery::append_recovery(&mut body, &self.recovery);
325	        body
326	    }
327	
328	    /// Render the response in the requested format.
329	    #[must_use]
330	    pub fn render(&self, format: OutputFormat) -> String {
331	        match format {
332	            OutputFormat::Text => self.render_text(),
333	            OutputFormat::Json => self.render_json(),
334	        }
335	    }
336	
337	    fn render_text(&self) -> String {
338	        let (body, _, extra) = self.body();
339	        self.finish_text(body, &extra)
340	    }
341	
342	    /// Whether this response is an error: `as_error()` was called, or a section's TOON rows or KV items failed
343	    /// validation and its block is a `toon_validation_failed` or `kv_validation_failed` error block. Validates
344	    /// without rendering.
345	    #[must_use]
346	    pub fn is_error(&self) -> bool {
347	        self.is_error
348	            || self.blocks().iter().any(|s| match &s.body {
349	                SectionBody::Toon { fields, rows } => {
350	                    self.section_options(&s.name, fields, rows, s.shown_total()).validate().is_err()
351	                }
352	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
353	                SectionBody::Text(_) => false,
354	            })
355	    }
356	
357	    /// Render just the `help[N]:` block for `self.hints`.
358	    #[must_use]
359	    pub fn render_hints_only(&self) -> String {
360	        crate::hints::render_hints(&self.hints)
361	    }
362	
363	    /// Render for the given audience.
364	    #[must_use]
365	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
366	        match audience {
367	            crate::audience::Audience::Assistant => self.render_text(),
368	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
369	        }
370	    }
371	
372	    /// Whether `.human_content()` was set on this builder.
373	    #[must_use]
374	    pub fn has_human_content(&self) -> bool {
375	        self.human_content.is_some()
376	    }
377	
378	    /// Build the MCP `CallToolResult` for this response.
379	    #[must_use]
380	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
381	        let (body, is_error, extra) = self.body();
382	        let structured_content = self.json_from_body(&body, is_error, &extra);
383	        let mut content = vec![crate::mcp::ContentBlock {
384	            text: self.finish_text(body, &extra),
385	            audience: vec![crate::audience::Audience::Assistant],
386	        }];
387	        if let Some(human) = &self.human_content {
388	            content.push(crate::mcp::ContentBlock {
389	                text: human.clone(),
390	                audience: vec![crate::audience::Audience::User],
391	            });
392	        }
393	        crate::mcp::CallToolResult { content, is_error, structured_content }
394	    }
395	
396	    fn render_json(&self) -> String {
397	        let (body, is_error, extra) = self.body();
398	        self.json_from_body(&body, is_error, &extra)
399	    }
400	
401	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
402	        let hints = self.hints_with(extra);
403	        let capacity =
404	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
405	        let mut out = String::with_capacity(capacity + body.len() + 128);
406	        out.push_str("{\"body\":");
407	        json_string(&mut out, body);
408	        if !self.sections.is_empty() {
409	            out.push_str(",\"sections\":[");
410	            for (i, s) in self.sections.iter().enumerate() {
411	                if i > 0 {
412	                    out.push(',');
413	                }
414	                push_section_json(&mut out, s);
415	            }
416	            out.push(']');
417	        }
418	        if let Some(b) = &self.budget {
419	            out.push_str(",\"budget\":");
420	            out.push_str(&crate::budget::budget_json(b));
421	        }
422	        if let Some(p) = &self.provenance {
423	            out.push_str(",\"provenance\":");
424	            out.push_str(&crate::provenance::provenance_json(p));
425	        }
426	        out.push_str(",\"hints\":[");
427	        for (i, h) in hints.iter().enumerate() {
428	            if i > 0 {
429	                out.push(',');
430	            }
431	            json_string(&mut out, h.as_str());
432	        }
433	        out.push_str("],\"recovery\":[");
434	        for (i, r) in self.recovery.iter().enumerate() {
435	            if i > 0 {
436	                out.push(',');
437	            }
438	            out.push_str("{\"tool\":");
439	            json_string(&mut out, &r.tool);
440	            out.push_str(",\"params\":");
441	            crate::recovery::push_params_json(&mut out, &r.params);
442	            if let Some(reason) = &r.reason {
443	                out.push_str(",\"reason\":");
444	                json_string(&mut out, reason);
445	            }
446	            out.push('}');
447	        }
448	        out.push_str("],\"isError\":");
449	        out.push_str(if is_error { "true" } else { "false" });
450	        out.push('}');
451	        out
452	    }
453	}
454	
455	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
456	fn validation_error_body(code: &str, message: &str) -> String {
457	    let message = crate::toon::escape_value(message);
458	    let mut out = String::with_capacity(17 + code.len() + message.len());
459	    out.push_str("error: ");
460	    out.push_str(code);
461	    out.push_str("\nmessage: ");
462	    out.push_str(&message);
463	    out
464	}
465	
466	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
467	struct Part<'a> {
468	    /// The block's name, the `section` column when several blocks share a root key.
469	    name: &'a str,
470	    /// The block's text without its `truncated` block or `totalCount` line.
471	    text: String,
472	    /// Cut cells as `(row, field name, chars removed)`.
473	    cuts: Vec<(usize, String, usize)>,
474	    /// The `totalCount` this block reports, when it reports one.
475	    total: Option<usize>,
476	}
477	
478	impl<'a> Part<'a> {
479	    /// A block that failed validation: the error body replaces its content and it reports no count.
480	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
481	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
482	    }
483	}
484	
485	/// A KV block as a part. No items still reports a larger total the caller set.
486	fn kv_part<'a>(name: &'a str, items: &[KvItem], total: Option<usize>) -> (Part<'a>, bool, Option<Hint>) {
487	    if items.is_empty() {
488	        return (Part { name, text: String::new(), cuts: Vec::new(), total }, false, None);
489	    }
490	    match crate::kv::render_kv(items, None, &[]) {
491	        Ok(text) => (Part { name, text, cuts: Vec::new(), total }, false, None),
492	        Err(e) => (Part::failed(name, "kv_validation_failed", &e.to_string()), true, None),
493	    }
494	}
495	
496	/// Append `block` after a LF unless either side is empty.
497	fn join_block(out: &mut String, block: &str) {
498	    if block.is_empty() {
499	        return;
500	    }
501	    if !out.is_empty() {
502	        out.push('\n');
503	    }
504	    out.push_str(block);
505	}
506	
507	/// The `truncated` block for the cuts of `parts`. A single block uses the inline shape
508	/// (`{row,field,removed}`); several share one table with a leading `section` column.
509	fn truncated_table(parts: &[Part<'_>]) -> String {
510	    use std::fmt::Write as _;
511	    let n: usize = parts.iter().map(|p| p.cuts.len()).sum();
512	    let mut out = String::with_capacity(48 + n * 32);
513	    let multi = parts.iter().filter(|p| !p.cuts.is_empty()).count() > 1;
514	    let _ = write!(out, "truncated[{n}]{}:", if multi { "{section,row,field,removed}" } else { "{row,field,removed}" });
515	    for p in parts {
516	        for (row, field, removed) in &p.cuts {
517	            out.push_str("\n  ");
518	            if multi {
519	                out.push_str(&crate::toon::escape_value(p.name));
520	                out.push(',');
521	            }
522	            let _ = write!(out, "{row},{},{removed}", crate::toon::escape_value(field));
523	        }
524	    }
525	    out
526	}
527	
528	/// The merged `totalCount[N]{section,total}:` table, for two or more blocks that report a total.
529	fn total_table(parts: &[Part<'_>]) -> String {
530	    use std::fmt::Write as _;
531	    let n = parts.iter().filter(|p| p.total.is_some()).count();
532	    let mut out = String::with_capacity(32 + n * 24);
533	    let _ = write!(out, "totalCount[{n}]{{section,total}}:");
534	    for p in parts {
535	        if let Some(total) = p.total {
536	            let _ = write!(out, "\n  {},{total}", crate::toon::escape_value(p.name));
537	        }
538	    }
539	    out
540	}
541	
542	/// A TOON cell value as JSON. Non-finite floats are `null`, as in the text render.
543	fn push_value_json(out: &mut String, v: &Value) {
544	    use std::fmt::Write as _;
545	    match v {
546	        Value::Str(s) => json_string(out, s),
547	        Value::Int(n) => {
548	            let _ = write!(out, "{n}");
549	        }
550	        Value::UInt(n) => {
551	            let _ = write!(out, "{n}");
552	        }
553	        Value::Float(f) => crate::toon::push_f64(out, *f),
554	        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
555	        _ => out.push_str("null"),
556	    }
557	}
558	
559	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
560	/// the text render, and `structuredContent` is the typed copy of the same data.
561	fn push_section_json(out: &mut String, s: &Section) {
562	    use std::fmt::Write as _;
563	    out.push_str("{\"name\":");
564	    json_string(out, &s.name);
565	    match &s.body {
566	        SectionBody::Toon { fields, rows } => {
567	            out.push_str(",\"kind\":\"toon\",\"fields\":[");
568	            for (i, f) in fields.iter().enumerate() {
569	                if i > 0 {
570	                    out.push(',');
571	                }
572	                json_string(out, f);
573	            }
574	            out.push_str("],\"rows\":[");
575	            for (i, row) in rows.iter().enumerate() {
576	                if i > 0 {
577	                    out.push(',');
578	                }
579	                out.push('[');
580	                for (j, cell) in row.iter().enumerate() {
581	                    if j > 0 {
582	                        out.push(',');
583	                    }
584	                    push_value_json(out, cell);
585	                }
586	                out.push(']');
587	            }
588	            out.push(']');
589	        }
590	        SectionBody::Kv(items) => {
591	            out.push_str(",\"kind\":\"kv\",\"items\":[");
592	            for (i, item) in items.iter().enumerate() {
593	                if i > 0 {
594	                    out.push(',');
595	                }
596	                out.push_str("{\"key\":");
597	                json_string(out, &item.key);
598	                out.push_str(",\"value\":");
599	                crate::kv::kv_value_to_json(out, &item.value);
600	                out.push('}');
601	            }
602	            out.push(']');
603	        }
604	        SectionBody::Text(text) => {
605	            out.push_str(",\"kind\":\"text\",\"text\":");
606	            json_string(out, text);
607	        }
608	    }
609	    let _ = write!(out, ",\"returnedCount\":{}", s.count());
610	    if let Some(total) = s.total_count {
611	        let _ = write!(out, ",\"totalCount\":{total}");
612	    }
613	    out.push_str(",\"truncated\":");
614	    out.push_str(if s.truncated { "true" } else { "false" });
615	    out.push('}');
616	}
617	
618	fn json_string(out: &mut String, s: &str) {
619	    crate::kv::json_escape_str(out, s);
620	}
