622	#[cfg(test)]
623	mod tests {
624	    use super::*;
625	
626	    #[test]
627	    fn capacity_violations_are_toon_validation_errors_on_every_surface() {
628	        let fields: Vec<String> = (0..=crate::toon::MAX_FIELDS).map(|i| format!("f{i}")).collect();
629	        let field_refs: Vec<&str> = fields.iter().map(String::as_str).collect();
630	        let too_wide = AgentResponse::new("t").items(vec![], &field_refs);
631	        let long_hint = AgentResponse::new("t")
632	            .items(vec![vec![Value::from("x")]], &["a"])
633	            .truncation_hint("h".repeat(crate::toon::MAX_TRUNCATION_HINT_CHARS + 1));
634	        for (r, message) in [
635	            (too_wide, "fields length 1001 exceeds maximum of 1000"),
636	            (long_hint, "truncation_hint length 257 chars exceeds maximum of 256"),
637	        ] {
638	            assert!(r.is_error(), "{message}");
639	            let text = r.render(OutputFormat::Text);
640	            assert_eq!(text, format!("error: toon_validation_failed\nmessage: {message}"));
641	            assert!(r.render(OutputFormat::Json).contains("\"isError\":true"), "{message}");
642	            let result = r.to_call_tool_result();
643	            assert!(result.is_error, "{message}");
644	            assert_eq!(result.content[0].text, text);
645	            assert!(result.structured_content.contains("\"isError\":true"), "{message}");
646	        }
647	    }
648	
649	    #[test]
650	    fn is_error_agrees_with_the_rendered_flag_for_every_target() {
651	        use crate::kv::{KvItem, KvValue};
652	        let kv = |key: &str| KvItem { key: key.into(), value: KvValue::Int(1) };
653	        let cases = [
654	            AgentResponse::new("t"),
655	            AgentResponse::new("help"),
656	            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a"]),
657	            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a", "b"]),
658	            AgentResponse::new("t").kv_items(vec![]),
659	            AgentResponse::new("t").kv_items(vec![kv("a")]),
660	            AgentResponse::new("t").kv_items(vec![kv("a"), kv("a")]),
661	            AgentResponse::new("t").kv_items(vec![kv("a")]).as_error(),
662	        ];
663	        for r in cases {
664	            assert_eq!(r.is_error(), r.to_call_tool_result().is_error, "{r:?}");
