17	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
18	#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
19	#[non_exhaustive]
20	pub struct BudgetSummary {
21	    /// Token ceiling the caller set.
22	    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
23	    pub max_tokens: Option<u64>,
