740	pub struct JsContentBlock {
741	    /// Always `"text"` — michi only ever produces text content blocks.
742	    #[napi(js_name = "type")]
743	    pub content_type: String,
744	    /// The block's text content.
745	    pub text: String,
746	    /// Which surface(s) this block is meant for.
747	    pub annotations: JsAnnotations,
748	}
749	
750	/// The MCP `CallToolResult` shape, returned by [`JsAgentResponse::to_call_tool_result`].
751	#[napi(object, js_name = "CallToolResult")]
752	#[derive(Debug, Clone)]
753	pub struct JsCallToolResult {
754	    /// Text content blocks.
755	    pub content: Vec<JsContentBlock>,
756	    /// Whether this is a tool execution error.
757	    #[napi(js_name = "isError")]
758	    pub is_error: bool,
759	    /// The JSON companion to `content[0]` (the `renderJson()` object), as a
760	    /// real parsed JSON value — not a string the caller has to `JSON.parse()`
761	    /// themselves.
762	    #[napi(js_name = "structuredContent")]
763	    pub structured_content: serde_json::Value,
764	}
765	
766	/// String bytes one [`JsAgentResponse`] holds, per slot. A slot that a call replaces (`truncationHint`,
767	/// `humanContent`) gives its old bytes back; `items`, `kvItems`, `hint` and `recoveryHint` each add a block, so they
768	/// only add.
769	#[derive(Debug, Default)]
770	struct HeldBytes {
771	    type_name: usize,
772	    items: usize,
773	    kv_items: usize,
774	    hints: usize,
775	    recovery: usize,
776	    truncation_hint: usize,
777	    human_content: usize,
778	}
779	
780	impl HeldBytes {
781	    fn total(&self) -> usize {
782	        [self.type_name, self.items, self.kv_items, self.hints, self.recovery, self.truncation_hint, self.human_content]
783	            .iter()
784	            .fold(0, |acc, n| acc.saturating_add(*n))
785	    }
786	
787	    /// An error if replacing a slot holding `old` bytes with `new` would take the total past
788	    /// [`input::MAX_INPUT_BYTES`]. Changes nothing: the caller stores the new slot size once its call succeeds.
789	    fn check_replace(&self, old: usize, new: usize) -> napi::Result<()> {
790	        let total = self.total().saturating_sub(old).saturating_add(new);
791	        if total > input::MAX_INPUT_BYTES {
792	            return Err(napi::Error::from_reason(format!(
793	                "cumulative byte total {total} exceeds maximum of {}",
794	                input::MAX_INPUT_BYTES
795	            )));
796	        }
797	        Ok(())
798	    }
799	}
800	
801	/// UTF-8 bytes of the string in one TOON cell (0 for other types).
802	fn cell_bytes(v: &JsToonValue) -> usize {
803	    v.str_val.as_ref().map_or(0, String::len)
804	}
805	
806	/// NAPI wrapper around [`crate::response::AgentResponse`].
807	///
808	/// Besides each call's own limits, one object holds at most 64 MiB of caller strings across all its calls (type name,
809	/// fields, cells, keys, hints, recovery hints, truncation hint and human content). A call that would pass that total
810	/// is rejected and leaves the builder unchanged; replacing `truncationHint` or `humanContent` gives the old value's
811	/// bytes back first. Every `items` and `kvItems` call adds a section, so their bytes add up.
812	#[napi(js_name = "AgentResponse")]
813	#[derive(Debug)]
814	pub struct JsAgentResponse {
815	    inner: Option<crate::response::AgentResponse>,
816	    /// The type name, which names the sections `items` and `kvItems` append.
817	    name: String,
818	    /// Cumulative count of [`Self::hint`] calls, capped at [`MAX_HINTS`].
819	    hint_count: usize,
820	    /// Cumulative count of [`Self::recovery_hint`] calls, capped at [`MAX_HINTS`].
821	    recovery_count: usize,
822	    /// String bytes held, capped at [`input::MAX_INPUT_BYTES`] in all.
823	    held: HeldBytes,
824	}
825	
826	#[napi]
827	impl JsAgentResponse {
828	    /// Create a new response builder for the given type name. The Rust-typed core of the JS constructor
829	    /// ([`Self::new_js`]); it does not cap the type name's length, though the name counts toward the 64 MiB total.
830	    #[must_use]
831	    pub fn new(type_name: String) -> Self {
832	        let held = HeldBytes { type_name: type_name.len(), ..HeldBytes::default() };
833	        let inner = Some(crate::response::AgentResponse::new(type_name.clone()));
834	        Self { inner, name: type_name, hint_count: 0, recovery_count: 0, held }
835	    }
836	
837	    /// The JS constructor, `new AgentResponse(typeName)`.
838	    ///
839	    /// # Errors
840	    ///
841	    /// Rejects a `typeName` over 4 KiB.
842	    #[napi(constructor, catch_unwind)]
843	    pub fn new_js(type_name: String) -> napi::Result<Self> {
844	        check_bytes("typeName", &type_name, MAX_NAME_BYTES)?;
845	        Ok(Self::new(type_name))
846	    }
847	
848	    fn take(&mut self) -> napi::Result<crate::response::AgentResponse> {
849	        self.inner.take().ok_or_else(|| napi::Error::from_reason("AgentResponse already consumed"))
850	    }
851	
852	    /// Append a TOON list section named for the response's type. Every call adds a section, rendered in call order.
853	    /// `totalCount`, when given, is how many rows existed before any cut; `totalCount: n` renders only when `n` is
854	    /// larger than the rows passed.
855	    ///
856	    /// # Errors
857	    ///
858	    /// Rejects, before converting anything, more than 100,000 rows, 1,000 fields or 1,000 values in a row, and
859	    /// more than 1,000,000 cells in all; while converting, a field name over 4 KiB, a cell over 1 MiB, more than
860	    /// 64 MiB of strings in the call, or an invalid cell; a `totalCount` that is not a finite, non-negative integer;
861	    /// then strings that would take the response past its 64 MiB total. The builder is unchanged on error.
862	    #[napi(
863	        catch_unwind,
864	        js_name = "items",
865	        ts_args_type = "rows: Array<Array<ToonValue>>, fields: Array<string>, totalCount?: number | null"
866	    )]
867	    pub fn items_js(
868	        &mut self,
869	        rows: Unknown<'_>,
870	        fields: Unknown<'_>,
871	        total_count: Option<JsCount>,
872	    ) -> napi::Result<()> {
873	        let mut budget = Budget::new();
874	        let rows = List::new(rows, "rows")?;
875	        let fields = List::new(fields, "fields")?;
876	        input::check_len("rows", rows.len(), MAX_ROWS)?;
877	        input::check_len("fields", fields.len(), MAX_FIELDS)?;
878	        let fields = budget.strings(&fields, "fields", MAX_FIELDS, "field name", MAX_NAME_BYTES)?;
879	        let rows = budget.rows(&rows, MAX_ROWS, MAX_FIELDS, "maximum")?;
880	        self.items(rows, fields, total_count)
881	    }
882	
883	    /// The Rust-typed core of the `items` method.
884	    ///
885	    /// # Errors
886	    ///
887	    /// Rejects more than `MAX_ROWS` rows or `MAX_FIELDS` fields or values in a row, an invalid cell, or strings that
888	    /// would take the response past its 64 MiB total.
889	    #[allow(clippy::needless_pass_by_value)] // mirrors the JS method, which hands over owned values
890	    pub fn items(
891	        &mut self,
892	        rows: Vec<Vec<JsToonValue>>,
893	        fields: Vec<String>,
894	        total_count: Option<JsCount>,
895	    ) -> napi::Result<()> {
896	        if rows.len() > MAX_ROWS {
897	            return Err(napi::Error::from_reason(format!("rows length {} exceeds maximum of {MAX_ROWS}", rows.len())));
898	        }
899	        if fields.len() > MAX_FIELDS {
900	            return Err(napi::Error::from_reason(format!(
901	                "fields length {} exceeds maximum of {MAX_FIELDS}",
902	                fields.len()
903	            )));
904	        }
905	        for row in &rows {
906	            if row.len() > MAX_FIELDS {
907	                return Err(napi::Error::from_reason(format!(
908	                    "row length {} exceeds maximum of {MAX_FIELDS}",
909	                    row.len()
910	                )));
911	            }
912	        }
913	        let bytes = fields
914	            .iter()
915	            .map(String::len)
916	            .chain(rows.iter().flatten().map(cell_bytes))
917	            .fold(0usize, usize::saturating_add);
918	        self.held.check_replace(0, bytes)?;
919	        let converted: Vec<Vec<crate::toon::Value>> = rows
920	            .into_iter()
921	            .map(|row| row.into_iter().map(js_value_to_rust).collect::<napi::Result<Vec<_>>>())
922	            .collect::<napi::Result<Vec<_>>>()?;
923	        let b = self.take()?;
924	        let name = self.name.clone();
925	        let section = crate::section::Section::toon(name, fields, converted).total_count(total_count.map(JsCount::get));
926	        self.inner = Some(b.section(section));
927	        self.held.items = self.held.items.saturating_add(bytes);
928	        Ok(())
929	    }
930	
931	    /// Append a KV section named for the response's type; the name is not printed. Every call adds a section,
932	    /// rendered in call order. `totalCount` works as in [`Self::items`].
933	    ///
934	    /// # Errors
935	    ///
936	    /// Rejects more than 1,000 items before converting any, a key over 4 KiB, a value over 1 MiB, more than 64 MiB
937	    /// of strings in the call, an invalid value, a `totalCount` that is not a finite, non-negative integer, or
938	    /// strings that would take the response past its 64 MiB total. The builder is unchanged on error.
939	    #[napi(catch_unwind, js_name = "kvItems", ts_args_type = "items: Array<KvItem>, totalCount?: number | null")]
940	    pub fn kv_items_js(&mut self, items: Unknown<'_>, total_count: Option<JsCount>) -> napi::Result<()> {
941	        let mut budget = Budget::new();
942	        let items = List::new(items, "items")?;
943	        let items = budget.kv_items(&items, MAX_FIELDS)?;
944	        self.kv_items(items, total_count)
